// Сборка отчёта ДЗ-1 (вариант 30) в .docx.
// Запуск: node build.js <out.docx>   (pages.json — номера страниц для оглавления, если уже посчитаны)
const fs = require('fs');
const path = require('path');
const D = require('docx');
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, Footer, PageNumber, TableOfContents, PageBreak,
} = D;
const { Doc, render, n, sgn, dev, FONT, numberingConfig } = require('./lib');

const ROOT = path.join(__dirname, '..');
const SIM = path.join(ROOT, 'sim');
const RUNS = path.join(SIM, 'runs');
const FIG = path.join(ROOT, 'fig');
const R = JSON.parse(fs.readFileSync(path.join(SIM, 'results.json')));
const E = JSON.parse(fs.readFileSync(path.join(SIM, 'extra.json')));
const PAGES = fs.existsSync(path.join(__dirname, 'pages.json'))
  ? JSON.parse(fs.readFileSync(path.join(__dirname, 'pages.json'))) : {};
const OUT = process.argv[2] || path.join(__dirname, 'report.docx');

// ---------- файлы ngspice ----------
const cir = (name) => fs.readFileSync(path.join(RUNS, name + '.cir'), 'utf8').trimEnd().split('\n');
const logLines = (name, re) => fs.readFileSync(path.join(RUNS, name + '.log'), 'latin1').split('\n')
  .filter((l) => re.test(l)).map((l) => l.trimEnd());
const MEAS_RE = /^(uavg|upp|umax|umin|ufavg|ufpp|izavg|izmin|izmax|ipusk|ipk|irms|iavg|iabs|ton|toff|tset|urev1|urev3|kp|kpf|tw) +=/;
const controlPart = (name) => { const L = cir(name); return L.slice(L.indexOf('.control')); };

// ---------- величины ----------
const PHI_T = 0.025865;                        // kT/q при 27 °C
const rd = (iz) => 0.3 * PHI_T / iz + 0.2313;  // r_диф стабилитрона BZX84C12VL по (3)
const T_MS = 1000 / 60;
const deg = (tw) => tw / (T_MS / 1000) * 360;
const mA = (x) => n(x * 1e3, x * 1e3 < 10 ? 2 : 1);
const iz = (r) => -r.Izavg;
const hw = R; const br = R;
const kp = (x) => n(x, x < 0.1 ? 4 : (x < 10 ? 3 : 2));
// «в N раз/раза»
const raz = (x, d = 0) => { const v = Number(x.toFixed(d)); const k = Math.round(v); const frac = d > 0 && v !== k; const ok = !frac && [2, 3, 4].includes(k % 10) && ![12, 13, 14].includes(k % 100); return `${n(v, d)} ${frac || ok ? 'раза' : 'раз'}`; };

const doc = new Doc();
const H1 = (id, t) => doc.h(1, id, t);
const H2 = (id, t) => doc.h(2, id, t);
const P = (t, o) => doc.p(t, o);
const NP = (t) => doc.p(t, { noind: true });
const EQ = (id, t) => doc.eq(id, t);

// ======================================================================
// 1 ТЕОРЕТИЧЕСКИЕ СВЕДЕНИЯ
// ======================================================================
H1('s1', '1 Теоретические сведения');
H2('s1_1', '1.1 Диод и стабилитрон. Модель в SPICE');
P('Диод — полупроводниковый прибор с одним p–n-переходом. При прямом смещении (потенциал анода выше потенциала катода) диод проводит ток, при обратном ток через него очень мал. Статическая вольт-амперная характеристика (ВАХ) диода без учёта пробоя описывается выражением [1]');
EQ('shockley', 'I_{Д} = I_{S}·[exp(V_{Д}/(m·φ_{T})) − 1],');
NP('где I_{S} — ток насыщения (параметр модели IS); m — коэффициент неидеальности (параметр N); φ_{T} = kT/q — тепловой потенциал, при 27 °C φ_{T} ≈ 25,9 мВ.');
P('Из-за экспоненциальной зависимости напряжение на открытом кремниевом диоде слабо меняется с током и составляет примерно 0,6–0,7 В. Это напряжение V_{Д,откр} используют в приближённых расчётах выпрямителей (модель диода с постоянным падением напряжения [2]). Кроме того, на ВАХ влияет последовательное сопротивление RS, а на работу диода в динамике — время пролёта TT (диффузионная ёмкость) и барьерная ёмкость перехода CJO.');
P('Стабилитрон работает на участке обратного пробоя. Ток на этом участке описывается выражением [1]');
EQ('zener', 'I_{Д} = I_{S}·[exp(−(V_{проб} + V_{Д})/(m_{BV}·φ_{T})) − 1],');
NP('где V_{проб} — напряжение пробоя (параметр BV, в моделях задаётся при токе IBV); m_{BV} — коэффициент неидеальности для участка пробоя (параметр NBV).');
P('Для расчёта стабилизатора понадобится дифференциальное сопротивление стабилитрона в рабочей точке. Если продифференцировать (@eq:zener) и добавить последовательное сопротивление RS, получится');
EQ('rd', 'r_{диф} = dV/dI ≈ m_{BV}·φ_{T}/I_{ст} + RS,');
NP('где I_{ст} — ток стабилитрона. Чем больше ток и чем меньше NBV, тем меньше r_{диф}, т. е. тем лучше стабилитрон «держит» напряжение.');
P('В SPICE-программах параметры диода задаются директивой .model, а каждый экземпляр диода ссылается на модель по имени:');
doc.lst(null, null, ['.model <имя_модели> D(<параметр>=<значение> ...)', 'D<имя> <узел_анода> <узел_катода> <имя_модели>']);
P('Параметры, которые не указаны в .model, принимают значения по умолчанию. По требованиям к работе имена моделей содержат фамилию исполнителя (например, D_Mosyagin), а имена элементов на схеме (D1, D2, …) от имён моделей отличаются.');

H2('s1_2', '1.2 Структура ИВЭП. Трансформатор');
P('Простейший линейный источник вторичного электропитания (ИВЭП) состоит из последовательно включённых трансформатора, выпрямителя, сглаживающего фильтра и стабилизатора напряжения, к выходу которого подключается нагрузка R_{н} [1, 2]. Трансформатор понижает сетевое напряжение до нужного уровня, выпрямитель делает напряжение однополярным, фильтр сглаживает пульсации, а стабилизатор поддерживает выходное напряжение постоянным при изменении входного напряжения и дополнительно ослабляет пульсации.');
P('Коэффициент трансформации равен отношению напряжений и чисел витков обмоток. В SPICE трансформатор задаётся двумя индуктивностями и элементом связи K, поэтому K_{тр} выражается через индуктивности обмоток [1]:');
EQ('ktr', 'K_{тр} = U_{1}/U_{2} = N_{1}/N_{2} = √(L_{1}/L_{2}).');
NP('Отсюда индуктивность первичной обмотки L_{1} = K_{тр}^{2}·L_{2}. Коэффициент связи в модели k = 0,99 (а не 1), поэтому амплитуда вторичного напряжения немного меньше идеальной: U_{2m} ≈ k·U_{1m}/K_{тр}.');

H2('s1_3', '1.3 Выпрямители');
P('Однополупериодный выпрямитель — это диод, включённый последовательно с нагрузкой. Диод открыт, пока входное напряжение превышает выходное на V_{Д,откр}, поэтому [1, 2]');
EQ('hw', 'U_{вых,m} = U_{вх,m} − V_{Д,откр};   U_{вых,ср} ≈ U_{вх,m}/π (без фильтра).');
P('В мостовом выпрямителе (диоды D1–D4) в каждом полупериоде ток проходит через два открытых диода, а отрицательная полуволна «переворачивается»:');
EQ('br', 'U_{вых,m} = U_{вх,m} − 2V_{Д,откр};   U_{вых,ср} ≈ 2U_{вх,m}/π (без фильтра).');
P('Пульсации на выходе моста имеют удвоенную частоту 2f. Обратное напряжение на закрытом диоде у однополупериодной схемы с конденсатором доходит примерно до 2U_{вх,m} (амплитуда входа плюс напряжение на конденсаторе), а у моста — примерно до U_{вх,m} [2]. Ещё одна особенность моста — у входа и выхода нет общей точки.');

H2('s1_4', '1.4 Сглаживающий фильтр и коэффициент пульсаций');
P('Простейший фильтр — конденсатор C_{ф} параллельно нагрузке. Конденсатор быстро заряжается через открытый диод вблизи максимума синусоиды и медленно разряжается через R_{н}, пока диод закрыт. Качество сглаживания оценивают коэффициентом пульсаций, который определяется в установившемся режиме [1]:');
EQ('kp', 'K_{пульс} = U_{вых,pp}/U_{вых,ср}·100 %,');
NP('где U_{вых,pp} — полный размах выходного напряжения (разность наибольшего и наименьшего значений), U_{вых,ср} — среднее значение на интервале, кратном периоду. В работе обе величины измеряются командами meas на интервале ровно 4 периода.');
P('При большой ёмкости разряд почти линейный и длится около периода (у моста — около половины периода), отсюда оценки размаха пульсаций [1, 2]:');
EQ('vp_hw', 'U_{пульс} ≈ (U_{вх,m} − V_{Д,откр})/(R_{н}·C_{ф}·f) — однополупериодный выпрямитель,');
EQ('vp_br', 'U_{пульс} ≈ (U_{вх,m} − 2V_{Д,откр})/(2R_{н}·C_{ф}·f) — мостовой выпрямитель,');
EQ('vavg', 'U_{вых,ср} ≈ U_{вых,m} − U_{пульс}/2.');
P('Так как U_{вых,ср} ≈ U_{вых,m}, из (@eq:kp)–(@eq:vp_br) получается удобная оценка коэффициента пульсаций (первая формула — для однополупериодного выпрямителя, вторая — для мостового):');
EQ('kest', 'K_{пульс} ≈ 100 %/(R_{н}·C_{ф}·f);    K_{пульс} ≈ 100 %/(2R_{н}·C_{ф}·f).');
P('Эти оценки справедливы, только если R_{н}C_{ф} заметно больше периода. Кроме того, сопротивление конденсатора на частоте сети должно быть много меньше сопротивления нагрузки [1]:');
EQ('xc', 'X_{C} = 1/(2π·f·C_{ф}) ≪ R_{н}.');

H2('s1_5', '1.5 Параметрический стабилизатор');
P('Параметрический стабилизатор состоит из балластного резистора R1 и стабилитрона (или цепочки стабилитронов и прямо включённых диодов), подключённого параллельно нагрузке. Выходное напряжение примерно равно сумме напряжений пробоя стабилитронов и прямых напряжений диодов V_{DDD}, а ток ветви стабилизатора без учёта нагрузки [1]');
EQ('istab', 'I_{DDD} = (U_{вх} − V_{DDD})/R1.');
NP('С подключённой нагрузкой через R1 течёт сумма токов стабилитрона и нагрузки: I_{R1} = I_{ст} + I_{н}.');
P('Для переменной составляющей стабилизатор работает как делитель из R1 и r_{диф}, поэтому пульсации на выходе [1]');
EQ('div', 'u_{вых} = u_{вх}·r_{диф}/(r_{диф} + R1).');
NP('Этим же отношением определяется коэффициент нестабильности по входу ΔU_{вых}/ΔU_{вх} [2]: почти всё изменение входного напряжения падает на R1.');

